-- contracts + calendar (2026-09-26, TODO.md §3): the two tables nothing owned.
--
-- contracts: front-month / expiry / roll for the symbols we trade. CME equity index futures
-- (NQ, MNQ, ES) expire on the THIRD FRIDAY of Mar/Jun/Sep/Dec at 09:30 ET; the customary roll
-- (volume moves to the next month) is the Thursday 8 days before expiry. If the third Friday
-- is an exchange holiday the contract expires the prior business day (Juneteenth 2027 falls
-- on Fri 18 Jun 2027 — flagged in `note`). Rows are GENERATED by rule (third_friday()), so a
-- typo is impossible, but a rule is not the rulebook: verify `roll_date` against the CME
-- product calendar once per quarter and correct the row if the exchange announces otherwise.
--
-- calendar: exchange holidays / early closes (CME Globex equity index, times in CT as CME
-- publishes them) and scheduled economic releases (ET). Rule-derived rows carry
-- source='rule'; hand-entered rows carry the source URL. Missing kinds (CPI/PPI/retail
-- sales) are deliberately NOT guessed — add them from the BLS schedule when needed.
--
-- Readers: nothing yet. Intended: grid/dashboard "next roll" warning, the executor's
-- news blackout (today hard-coded 08:30/10:00/14:00/14:30 in orb_strategy.hpp) and
-- session_stats (holiday-shortened sessions).

CREATE OR REPLACE FUNCTION third_friday(p_year int, p_month int) RETURNS date
LANGUAGE sql IMMUTABLE AS $$
  SELECT (make_date(p_year, p_month, 1)
          + ((5 - extract(dow FROM make_date(p_year, p_month, 1))::int + 7) % 7)   -- first Friday
          + 14)::date                                                            -- third Friday
$$;

CREATE TABLE IF NOT EXISTS contracts (
    symbol         text NOT NULL,          -- NQ | MNQ | ES
    contract       text NOT NULL,          -- NQZ6 (CME month code + year digit)
    month_code     char(1) NOT NULL,       -- H M U Z
    expiry_date    date NOT NULL,          -- third Friday 09:30 ET (or prior business day)
    roll_date      date NOT NULL,          -- Thursday 8 days before expiry (volume roll)
    first_trade    date,                   -- when this contract becomes front month (= prior roll_date)
    note           text,
    source         text NOT NULL DEFAULT 'rule',
    PRIMARY KEY (symbol, contract)
);

-- Generate Dec 2026 .. Sep 2027 for NQ / MNQ / ES.
INSERT INTO contracts (symbol, contract, month_code, expiry_date, roll_date, first_trade, note)
SELECT s.symbol,
       s.symbol || m.code || right(m.yr::text, 1),
       m.code,
       CASE WHEN third_friday(m.yr, m.mon) = DATE '2027-06-18'
            THEN DATE '2027-06-17' ELSE third_friday(m.yr, m.mon) END,
       third_friday(m.yr, m.mon) - 8,
       lag(third_friday(m.yr, m.mon) - 8) OVER (PARTITION BY s.symbol ORDER BY m.yr, m.mon),
       CASE WHEN third_friday(m.yr, m.mon) = DATE '2027-06-18'
            THEN 'third Friday is Juneteenth (exchange holiday) — expires Thu 17 Jun 2027; VERIFY with CME'
            ELSE NULL END
FROM (VALUES ('NQ'), ('MNQ'), ('ES')) AS s(symbol)
CROSS JOIN (VALUES (2026, 9, 'U'), (2026, 12, 'Z'), (2027, 3, 'H'), (2027, 6, 'M'), (2027, 9, 'U')) AS m(yr, mon, code)
ON CONFLICT (symbol, contract) DO NOTHING;

-- The front month on a given date (roll-date aware).
CREATE OR REPLACE FUNCTION front_month(p_symbol text, p_date date DEFAULT current_date) RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT contract FROM contracts
  WHERE symbol = p_symbol AND roll_date > p_date
  ORDER BY expiry_date LIMIT 1
$$;

CREATE TABLE IF NOT EXISTS calendar (
    day         date NOT NULL,
    kind        text NOT NULL,      -- holiday | early_close | fomc | nfp
    label       text NOT NULL,
    time_et     time,               -- release time (ET) for economic events; NULL for holidays
    close_ct    time,               -- early-close time in CT as CME states it (NULL = closed all day)
    note        text,
    source      text NOT NULL,
    PRIMARY KEY (day, kind)
);

