-- Non-farm payrolls: first Friday of the month at 08:30 ET (rule; BLS shifts it when the
-- first Friday is a holiday or falls on the 1st/2nd — Jan 2027 is the 8th for that reason).
INSERT INTO calendar (day, kind, label, time_et, note, source)
SELECT d, 'nfp', 'Non-farm payrolls', '08:30',
       CASE WHEN d = DATE '2027-01-01' THEN 'BLS moves this to Jan 8 (holiday) — corrected below' END,
       'rule: first Friday'
FROM (SELECT (make_date(y, m, 1) + ((5 - extract(dow FROM make_date(y, m, 1))::int + 7) % 7))::date AS d
      FROM (VALUES (2026,10),(2026,11),(2026,12),(2027,2),(2027,3),(2027,4)) AS ym(y, m)) f
ON CONFLICT (day, kind) DO NOTHING;
INSERT INTO calendar (day, kind, label, time_et, note, source) VALUES
 ('2027-01-08', 'nfp', 'Non-farm payrolls', '08:30', 'first Friday is New Year''s Day', 'rule: first Friday (holiday-shifted)')
ON CONFLICT (day, kind) DO NOTHING;

-- Convenience: everything that matters in the next N days.
CREATE OR REPLACE FUNCTION upcoming_events(p_days int DEFAULT 14)
RETURNS TABLE (day date, kind text, label text, time_et time, close_ct time, note text)
LANGUAGE sql STABLE AS $$
  SELECT day, kind, label, time_et, close_ct, note FROM calendar
  WHERE day BETWEEN current_date AND current_date + p_days
  UNION ALL
  SELECT roll_date, 'roll', symbol || ' roll → ' || contract, NULL, NULL,
         'front month becomes ' || contract || ' (expiry ' || expiry_date || ')'
  FROM contracts WHERE roll_date BETWEEN current_date AND current_date + p_days
  ORDER BY 1, 2
$$;
